import { MoneyText } from "@/components/MoneyText";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { actualsForFinancialPlanMonth, financialPlanAvailableCents, financialPlanCoverage, financialPlanScenarioCoverage, financialPlanScenarioForIncome, monthInputValue } from "@/lib/financialPlanUtils";
import { exportFinancialPlanPdf } from "@/lib/financialPlanExport";
import { trpc } from "@/lib/trpc";
import { AlertTriangle, Archive, ArrowRight, BarChart3, CalendarDays, CalendarRange, CheckCircle2, ChevronLeft, ChevronRight, CircleDollarSign, ClipboardList, Download, Flag, Link2, ListTodo, Pencil, Plus, SlidersHorizontal, Target, Trash2 } from "lucide-react";
import { FormEvent, useMemo, useState } from "react";
import { toast } from "sonner";

type WorkspaceData = any;
type FinancialPlanTab = "summary" | "months" | "comparison" | "calendar" | "scenarios" | "levels" | "links";
const statusLabels: Record<string, string> = { draft: "Borrador", active: "Activo", completed: "Completado", archived: "Archivado", in_review: "En revisión", complete: "Revisado" };
const resourceLabels: Record<string, string> = { budget: "Presupuesto", debt: "Deuda", credit_card: "Tarjeta", payable: "CxP", receivable: "CxC", goal: "Objetivo", task: "Tarea", calendar_event: "Calendario", fiscal_review: "Revisión fiscal", document: "Documento" };
const scenarioTone: Record<string, string> = { rose: "border-rose-200 bg-rose-50 text-rose-800", amber: "border-amber-200 bg-amber-50 text-amber-800", sky: "border-sky-200 bg-sky-50 text-sky-800", emerald: "border-emerald-200 bg-emerald-50 text-emerald-800", slate: "border-slate-200 bg-slate-50 text-slate-800" };
const monthLabel = (value: Date | string) => new Intl.DateTimeFormat("es-MX", { month: "long", year: "numeric" }).format(new Date(value));
const dateInputValue = (value: Date | string | null | undefined) => value ? new Date(value).toISOString().slice(0, 10) : "";
const asDateTimestamp = (value: string) => value ? new Date(`${value}T12:00:00`).getTime() : null;
const centsFromInput = (value: string) => Math.max(0, Math.round((Number(value) || 0) * 100));
const inputFromCents = (value: number | null | undefined) => value == null ? "" : String(value / 100);

export function FinancialPlanWorkspace({ data, isOwner, onRefresh }: { data: WorkspaceData; isOwner: boolean; onRefresh: () => Promise<void> }) {
  const [tab, setTab] = useState<FinancialPlanTab>("summary");
  const [planEditing, setPlanEditing] = useState<any | null>(null);
  const [planOpen, setPlanOpen] = useState(false);
  const [levelEditing, setLevelEditing] = useState<any | null>(null);
  const [scenarioEditing, setScenarioEditing] = useState<any | null>(null);
  const [periodEditing, setPeriodEditing] = useState<any | null>(null);
  const [linkEditing, setLinkEditing] = useState<any | null>(null);
  const [editor, setEditor] = useState<"level" | "scenario" | "period" | "link" | null>(null);
  const plans = data.financialPlans ?? [];
  const projects = (data.projects ?? []).filter((project: any) => project.status !== "archived");
  const projectsWithoutPlan = projects.filter((project: any) => !plans.some((plan: any) => plan.projectId === project.id));
  const [selectedPlanId, setSelectedPlanId] = useState<number | null>(plans[0]?.id ?? null);
  const selectedPlan = plans.find((plan: any) => plan.id === selectedPlanId) ?? plans[0] ?? null;
  const selectedProject = selectedPlan ? projects.find((project: any) => project.id === selectedPlan.projectId) : null;
  const levels = useMemo(() => (data.financialPlanLevels ?? []).filter((level: any) => level.financialPlanId === selectedPlan?.id).sort((a: any, b: any) => a.position - b.position), [data.financialPlanLevels, selectedPlan?.id]);
  const scenarios = useMemo(() => (data.financialPlanScenarios ?? []).filter((scenario: any) => scenario.financialPlanId === selectedPlan?.id).sort((a: any, b: any) => (a.incomeFloorCents ?? -1) - (b.incomeFloorCents ?? -1)), [data.financialPlanScenarios, selectedPlan?.id]);
  const periods = useMemo(() => (data.financialPlanPeriods ?? []).filter((period: any) => period.financialPlanId === selectedPlan?.id).sort((a: any, b: any) => new Date(a.periodStart).getTime() - new Date(b.periodStart).getTime()), [data.financialPlanPeriods, selectedPlan?.id]);
  const links = useMemo(() => (data.financialPlanLinks ?? []).filter((link: any) => link.financialPlanId === selectedPlan?.id), [data.financialPlanLinks, selectedPlan?.id]);
  const [selectedPeriodId, setSelectedPeriodId] = useState<number | null>(null);
  const [calendarAnchor, setCalendarAnchor] = useState(() => new Date());
  const selectedPeriod = periods.find((period: any) => period.id === selectedPeriodId) ?? periods[0] ?? null;

  const refreshAndClose = async () => { await onRefresh(); setEditor(null); setPlanOpen(false); setPlanEditing(null); setLevelEditing(null); setScenarioEditing(null); setPeriodEditing(null); setLinkEditing(null); };
  const planSave = trpc.finance.financialPlans.save.useMutation({ onSuccess: async result => { await onRefresh(); setSelectedPlanId(result.id); setPlanOpen(false); setPlanEditing(null); toast.success("Plan financiero guardado."); }, onError: error => toast.error(error.message) });
  const planRemove = trpc.finance.financialPlans.remove.useMutation({ onSuccess: async () => { await onRefresh(); setSelectedPlanId(null); toast.success("Plan financiero eliminado."); }, onError: error => toast.error(error.message) });
  const levelSave = trpc.finance.financialPlans.levelSave.useMutation({ onSuccess: async () => { await refreshAndClose(); toast.success("Prioridad guardada."); }, onError: error => toast.error(error.message) });
  const levelRemove = trpc.finance.financialPlans.levelRemove.useMutation({ onSuccess: async () => { await onRefresh(); toast.success("Prioridad eliminada."); }, onError: error => toast.error(error.message) });
  const scenarioSave = trpc.finance.financialPlans.scenarioSave.useMutation({ onSuccess: async () => { await refreshAndClose(); toast.success("Escenario guardado."); }, onError: error => toast.error(error.message) });
  const scenarioRemove = trpc.finance.financialPlans.scenarioRemove.useMutation({ onSuccess: async () => { await onRefresh(); toast.success("Escenario eliminado."); }, onError: error => toast.error(error.message) });
  const periodSave = trpc.finance.financialPlans.periodSave.useMutation({ onSuccess: async () => { await refreshAndClose(); toast.success("Mes del plan guardado."); }, onError: error => toast.error(error.message) });
  const periodRemove = trpc.finance.financialPlans.periodRemove.useMutation({ onSuccess: async () => { await onRefresh(); toast.success("Mes del plan eliminado."); }, onError: error => toast.error(error.message) });
  const linkSave = trpc.finance.financialPlans.linkSave.useMutation({ onSuccess: async () => { await refreshAndClose(); toast.success("Referencia vinculada. No se modificó el registro original."); }, onError: error => toast.error(error.message) });
  const linkRemove = trpc.finance.financialPlans.linkRemove.useMutation({ onSuccess: async () => { await onRefresh(); toast.success("Referencia eliminada."); }, onError: error => toast.error(error.message) });

  const currentActuals = selectedPlan && selectedPeriod ? actualsForFinancialPlanMonth(data.transactions ?? [], selectedPlan.projectId, selectedPlan.currency, selectedPeriod.periodStart) : { incomeCents: 0, expenseCents: 0, savingsCents: 0 };
  const currentScenario = selectedPlan ? financialPlanScenarioForIncome(scenarios, currentActuals.incomeCents) : null;
  const availableCents = selectedPeriod ? financialPlanAvailableCents(selectedPeriod.expectedIncomeCents, selectedPeriod.plannedCommitmentsCents, selectedPeriod.plannedSavingsCents) : 0;

  if (!projects.length) return <Card className="border-dashed"><CardHeader><p className="eyebrow">Plan financiero</p><CardTitle>Primero crea un proyecto</CardTitle><CardDescription>La planificación mensual vive dentro de un proyecto para conservar el contexto, las tareas y sus referencias.</CardDescription></CardHeader></Card>;

  return <section className="space-y-4" aria-label="Plan financiero">
    <header className="flex flex-col gap-3 rounded-2xl border bg-card p-4 shadow-sm sm:flex-row sm:items-end sm:justify-between sm:p-5">
      <div><p className="eyebrow">Plan financiero</p><h2 className="mt-1 text-xl font-semibold tracking-[-0.04em]">Prioridades, meses y escenarios</h2><p className="mt-1 max-w-2xl text-sm leading-6 text-muted-foreground">Planea con importes manuales y compara sólo contra movimientos confirmados del proyecto. No se crean pagos ni asignaciones automáticas.</p></div>
      <div className="flex flex-wrap gap-2">{plans.length ? <Select value={String(selectedPlan?.id ?? "")} onValueChange={value => { setSelectedPlanId(Number(value)); setSelectedPeriodId(null); }}><SelectTrigger className="w-[13rem]"><SelectValue placeholder="Selecciona un plan"/></SelectTrigger><SelectContent>{plans.map((plan: any) => <SelectItem key={plan.id} value={String(plan.id)}>{plan.title}</SelectItem>)}</SelectContent></Select> : null}{isOwner && projectsWithoutPlan.length ? <Button className="btn-primary" onClick={() => { setPlanEditing(null); setPlanOpen(true); }}><Plus className="mr-1.5 size-4"/>Plan financiero</Button> : null}{selectedPlan ? <Button variant="outline" onClick={() => exportFinancialPlanPdf({ plan: selectedPlan, periods, scenarios, transactions: data.transactions ?? [] })}><Download className="mr-1.5 size-4"/>Exportar PDF</Button> : null}</div>
    </header>
    {!selectedPlan ? <EmptyFinancialPlan isOwner={isOwner} projects={projectsWithoutPlan} onCreate={() => { setPlanEditing(null); setPlanOpen(true); }} /> : <>
      <nav className="-mx-1 flex gap-1 overflow-x-auto border-b px-1 pb-2 [scrollbar-width:none]" aria-label="Vistas del Plan Financiero">{([{ value: "summary", label: "Resumen", icon: CircleDollarSign }, { value: "months", label: "Meses", icon: CalendarDays }, { value: "comparison", label: "Plan vs. real", icon: BarChart3 }, { value: "calendar", label: "Calendario", icon: CalendarRange }, { value: "scenarios", label: "Escenarios", icon: SlidersHorizontal }, { value: "levels", label: "Prioridades", icon: Target }, { value: "links", label: "Referencias", icon: Link2 }] as const).map(option => { const Icon = option.icon; return <button key={option.value} type="button" onClick={() => setTab(option.value)} className={`flex shrink-0 items-center gap-2 rounded-lg px-3 py-2 text-sm font-semibold transition ${tab === option.value ? "bg-primary text-primary-foreground shadow-sm" : "text-muted-foreground hover:bg-muted hover:text-foreground"}`} aria-current={tab === option.value ? "page" : undefined}><Icon className="size-4"/>{option.label}</button>; })}</nav>
      {tab === "summary" ? <FinancialPlanSummary plan={selectedPlan} project={selectedProject} periods={periods} levels={levels} scenarios={scenarios} selectedPeriod={selectedPeriod} onPeriodChange={setSelectedPeriodId} actuals={currentActuals} availableCents={availableCents} currentScenario={currentScenario} isOwner={isOwner} onEdit={() => { setPlanEditing(selectedPlan); setPlanOpen(true); }} onRemove={() => { if (window.confirm("¿Eliminar este plan y sus prioridades, escenarios, meses y referencias? Esta acción no modifica movimientos, pagos ni objetivos.")) planRemove.mutate({ id: selectedPlan.id }); }} /> : null}
      {tab === "months" ? <FinancialPlanPeriods plan={selectedPlan} periods={periods} links={links} goals={data.goals ?? []} transactions={data.transactions ?? []} isOwner={isOwner} onManageLinks={() => setTab("links")} onAdd={() => { setPeriodEditing(null); setEditor("period"); }} onEdit={(period: any) => { setPeriodEditing(period); setEditor("period"); }} onRemove={(period: any) => { if (window.confirm(`¿Eliminar ${monthLabel(period.periodStart)} del plan?`)) periodRemove.mutate({ id: period.id }); }} /> : null}
      {tab === "comparison" ? <FinancialPlanComparison plan={selectedPlan} periods={periods} links={links} goals={data.goals ?? []} transactions={data.transactions ?? []} scenarios={scenarios} onManageLinks={() => setTab("links")} /> : null}
      {tab === "calendar" ? <FinancialPlanCalendar plan={selectedPlan} periods={periods} links={links} goals={data.goals ?? []} tasks={data.tasks ?? []} calendarEvents={data.calendarEvents ?? []} anchor={calendarAnchor} onAnchorChange={setCalendarAnchor} /> : null}
      {tab === "scenarios" ? <FinancialPlanScenarios plan={selectedPlan} scenarios={scenarios} levels={levels} isOwner={isOwner} onAdd={() => { setScenarioEditing(null); setEditor("scenario"); }} onEdit={(scenario: any) => { setScenarioEditing(scenario); setEditor("scenario"); }} onRemove={(scenario: any) => { if (window.confirm(`¿Eliminar el escenario «${scenario.title}»?`)) scenarioRemove.mutate({ id: scenario.id }); }} /> : null}
      {tab === "levels" ? <FinancialPlanLevels plan={selectedPlan} levels={levels} isOwner={isOwner} onAdd={() => { setLevelEditing(null); setEditor("level"); }} onEdit={(level: any) => { setLevelEditing(level); setEditor("level"); }} onRemove={(level: any) => { if (window.confirm(`¿Eliminar la prioridad «${level.title}»? Las referencias deben reasignarse primero.`)) levelRemove.mutate({ id: level.id }); }} /> : null}
      {tab === "links" ? <FinancialPlanLinks data={data} plan={selectedPlan} levels={levels} periods={periods} links={links} isOwner={isOwner} onAdd={() => { setLinkEditing(null); setEditor("link"); }} onEdit={(link: any) => { setLinkEditing(link); setEditor("link"); }} onRemove={(link: any) => { if (window.confirm("¿Eliminar esta referencia? El dato financiero original no cambiará.")) linkRemove.mutate({ id: link.id }); }} /> : null}
    </>}
    <Dialog open={planOpen} onOpenChange={value => { setPlanOpen(value); if (!value) setPlanEditing(null); }}>{planOpen ? <FinancialPlanForm key={planEditing?.id ?? "new"} plan={planEditing} projects={planEditing ? projects.filter((project: any) => project.id === planEditing.projectId || !plans.some((entry: any) => entry.projectId === project.id)) : projectsWithoutPlan} defaultProjectId={selectedPlan?.projectId ?? projectsWithoutPlan[0]?.id} saving={planSave.isPending} onSubmit={(input: any) => planSave.mutate(input)} /> : null}</Dialog>
    <Dialog open={editor === "level"} onOpenChange={value => !value && setEditor(null)}>{editor === "level" && selectedPlan ? <LevelForm key={levelEditing?.id ?? "new"} item={levelEditing} plan={selectedPlan} saving={levelSave.isPending} onSubmit={(input: any) => levelSave.mutate(input)} /> : null}</Dialog>
    <Dialog open={editor === "scenario"} onOpenChange={value => !value && setEditor(null)}>{editor === "scenario" && selectedPlan ? <ScenarioForm key={scenarioEditing?.id ?? "new"} item={scenarioEditing} plan={selectedPlan} levels={levels} saving={scenarioSave.isPending} onSubmit={(input: any) => scenarioSave.mutate(input)} /> : null}</Dialog>
    <Dialog open={editor === "period"} onOpenChange={value => !value && setEditor(null)}>{editor === "period" && selectedPlan ? <PeriodForm key={periodEditing?.id ?? "new"} item={periodEditing} plan={selectedPlan} saving={periodSave.isPending} onSubmit={(input: any) => periodSave.mutate(input)} /> : null}</Dialog>
    <Dialog open={editor === "link"} onOpenChange={value => !value && setEditor(null)}>{editor === "link" && selectedPlan ? <LinkForm key={linkEditing?.id ?? "new"} item={linkEditing} data={data} plan={selectedPlan} levels={levels} periods={periods} saving={linkSave.isPending} onSubmit={(input: any) => linkSave.mutate(input)} /> : null}</Dialog>
  </section>;
}

function EmptyFinancialPlan({ isOwner, onCreate }: { isOwner: boolean; projects: any[]; onCreate: () => void }) { return <Card className="border-dashed"><CardContent className="py-12 text-center"><span className="mx-auto grid size-11 place-items-center rounded-2xl bg-primary/10 text-primary"><ClipboardList className="size-5"/></span><h3 className="mt-4 text-base font-semibold">Sin plan financiero en este proyecto</h3><p className="mx-auto mt-2 max-w-xl text-sm leading-6 text-muted-foreground">Crea y completa manualmente la estructura del plan. Las fechas, escenarios, compromisos y referencias se guardan sólo cuando los introduces o editas.</p>{isOwner ? <div className="mx-auto mt-5 flex max-w-md justify-center"><Button className="btn-primary" onClick={onCreate}><Plus className="mr-1.5 size-4"/>Crear plan financiero</Button></div> : null}</CardContent></Card>; }

function FinancialPlanSummary({ plan, project, periods, levels, scenarios, selectedPeriod, onPeriodChange, actuals, availableCents, currentScenario, isOwner, onEdit, onRemove }: any) {
  const metrics = selectedPeriod ? [{ label: "Ingreso confirmado", value: <MoneyText cents={actuals.incomeCents} currency={plan.currency} />, detail: "Movimientos confirmados" }, { label: "Gasto confirmado", value: <MoneyText cents={-actuals.expenseCents} currency={plan.currency} />, detail: "Sólo gastos comparables" }, { label: "Disponible planeado", value: <MoneyText cents={availableCents} currency={plan.currency} signed />, detail: "Esperado menos compromisos y ahorro" }] : [];
  return <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_20rem]"><div className="space-y-4"><Card><CardHeader className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><p className="eyebrow">{project?.name ?? "Proyecto"}</p><CardTitle className="mt-1">{plan.title}</CardTitle><CardDescription className="mt-2">{plan.guidingRule || "Sin regla guía. Añade una para conservar el criterio de asignación manual."}</CardDescription></div><div className="flex items-center gap-2"><Badge variant="outline">{statusLabels[plan.status]}</Badge>{isOwner ? <Button size="icon" variant="ghost" aria-label="Editar plan financiero" onClick={onEdit}><Pencil className="size-4"/></Button> : null}</div></CardHeader><CardContent>{periods.length ? <div className="flex flex-col gap-3 rounded-xl border bg-muted/20 p-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-xs font-semibold">Mes de referencia</p><p className="mt-1 text-[11px] text-muted-foreground">Los reales provienen sólo de movimientos confirmados del proyecto.</p></div><Select value={String(selectedPeriod?.id ?? "")} onValueChange={value => onPeriodChange(Number(value))}><SelectTrigger className="w-full sm:w-[12rem]"><SelectValue/></SelectTrigger><SelectContent>{periods.map((period: any) => <SelectItem key={period.id} value={String(period.id)}>{monthLabel(period.periodStart)}</SelectItem>)}</SelectContent></Select></div> : <div className="rounded-xl border border-dashed p-4 text-sm text-muted-foreground">Añade el primer mes para ver seguimiento mensual.</div>}</CardContent></Card>{selectedPeriod ? <div className="grid gap-3 sm:grid-cols-3">{metrics.map(metric => <Card key={metric.label}><CardContent className="p-4"><p className="text-[10px] font-bold uppercase tracking-[0.1em] text-muted-foreground">{metric.label}</p><strong className="mt-2 block text-xl font-semibold tracking-[-0.04em]">{metric.value}</strong><p className="mt-2 text-[11px] leading-5 text-muted-foreground">{metric.detail}</p></CardContent></Card>)}</div> : null}<Card><CardHeader><CardTitle className="text-base">Prioridades de asignación</CardTitle><CardDescription>Se presentan en el orden que determines. El plan no mueve dinero ni marca pagos como realizados.</CardDescription></CardHeader><CardContent className="space-y-2">{levels.length ? levels.map((level: any) => <div className="flex items-center gap-3 rounded-xl border p-3" key={level.id}><span className="grid size-7 shrink-0 place-items-center rounded-full bg-primary/10 text-xs font-bold text-primary">{level.position}</span><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{level.title}</p>{level.activationRule ? <p className="mt-0.5 truncate text-[11px] text-muted-foreground">{level.activationRule}</p> : null}</div><MoneyText cents={level.monthlyTargetCents} currency={plan.currency} /></div>) : <p className="rounded-xl bg-muted/50 p-4 text-sm text-muted-foreground">Aún no hay prioridades. Registra el orden en que deseas cubrir compromisos con ingresos confirmados.</p>}</CardContent></Card></div><aside className="space-y-4"><Card><CardHeader><CardTitle className="text-base">Escenario activo</CardTitle><CardDescription>Referencia calculada con el ingreso confirmado del mes seleccionado.</CardDescription></CardHeader><CardContent>{currentScenario ? <div className={`rounded-xl border p-4 ${scenarioTone[currentScenario.colorKey]}`}><p className="text-sm font-semibold">{currentScenario.title}</p><p className="mt-2 text-xs leading-5">Hasta prioridad {currentScenario.allocationThroughPosition}. {currentScenario.guidance || "Sin guía adicional."}</p></div> : <p className="rounded-xl bg-muted/50 p-4 text-sm leading-6 text-muted-foreground">No hay un escenario que cubra el ingreso confirmado. Crea rangos manuales para obtener una referencia.</p>}</CardContent></Card><Card><CardHeader><CardTitle className="text-base">Planificación del mes</CardTitle></CardHeader>{selectedPeriod ? <CardContent className="space-y-3 text-sm"><PlanLine label="Ingreso esperado" value={<MoneyText cents={selectedPeriod.expectedIncomeCents} currency={plan.currency} />} /><PlanLine label="Compromisos planeados" value={<MoneyText cents={-selectedPeriod.plannedCommitmentsCents} currency={plan.currency} />} /><PlanLine label="Ahorro planeado" value={<MoneyText cents={-selectedPeriod.plannedSavingsCents} currency={plan.currency} />} /><div className="border-t pt-3"><PlanLine label="Disponible planeado" strong value={<MoneyText cents={availableCents} currency={plan.currency} signed />} /></div></CardContent> : <CardContent><p className="text-sm text-muted-foreground">Añade meses para ver esta planificación.</p></CardContent>}</Card>{isOwner ? <Button variant="outline" className="w-full text-rose-700 hover:bg-rose-50 hover:text-rose-800" onClick={onRemove}><Trash2 className="mr-1.5 size-4"/>Eliminar plan</Button> : null}</aside></div>;
}

function PlanLine({ label, value, strong = false }: { label: string; value: any; strong?: boolean }) { return <div className="flex items-center justify-between gap-3"><span className={strong ? "font-semibold" : "text-muted-foreground"}>{label}</span><span className={strong ? "font-semibold" : "font-medium"}>{value}</span></div>; }

function FinancialPlanPeriods({ plan, periods, links, goals, transactions, isOwner, onManageLinks, onAdd, onEdit, onRemove }: any) { return <Card><CardHeader className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="eyebrow">Vista mensual</p><CardTitle className="mt-1">Plan vs. movimientos confirmados</CardTitle><CardDescription>Los importes reales se leen de tus registros confirmados y no crean un cierre mensual.</CardDescription></div>{isOwner ? <Button className="btn-primary" onClick={onAdd}><Plus className="mr-1.5 size-4"/>Mes del plan</Button> : null}</CardHeader><CardContent>{periods.length ? <div className="space-y-3">{periods.map((period: any) => { const actuals = actualsForFinancialPlanMonth(transactions, plan.projectId, plan.currency, period.periodStart); const available = financialPlanAvailableCents(period.expectedIncomeCents, period.plannedCommitmentsCents, period.plannedSavingsCents); const coverage = financialPlanCoverage(period.expectedIncomeCents, period.plannedCommitmentsCents); const periodGoals = links.filter((link: any) => link.financialPlanPeriodId === period.id && link.resourceType === "goal").map((link: any) => goals.find((goal: any) => goal.id === link.resourceId)).filter(Boolean); return <article key={period.id} className="rounded-xl border p-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><div className="flex flex-wrap items-center gap-2"><h3 className="text-sm font-semibold capitalize">{monthLabel(period.periodStart)}</h3><Badge variant="outline">{statusLabels[period.status]}</Badge></div>{period.notes ? <p className="mt-1 text-xs leading-5 text-muted-foreground">{period.notes}</p> : null}<div className="mt-2 flex flex-wrap items-center gap-1">{periodGoals.length ? periodGoals.map((goal: any) => <Badge key={goal.id} variant="secondary"><Target className="mr-1 size-3"/>{goal.name}</Badge>) : <span className="text-[11px] text-muted-foreground">Sin objetivos asociados</span>}{isOwner ? <Button size="sm" variant="ghost" className="ml-auto" onClick={onManageLinks}><Link2 className="mr-1 size-3.5"/>Vincular</Button> : null}</div></div>{isOwner ? <div className="flex gap-1"><Button size="icon" variant="ghost" aria-label={`Editar ${monthLabel(period.periodStart)}`} onClick={() => onEdit(period)}><Pencil className="size-4"/></Button><Button size="icon" variant="ghost" className="text-muted-foreground hover:bg-rose-50 hover:text-rose-700" aria-label={`Eliminar ${monthLabel(period.periodStart)}`} onClick={() => onRemove(period)}><Trash2 className="size-4"/></Button></div> : null}</div>{!coverage.isCovered ? <div className="mt-4 flex items-start gap-2 rounded-xl border border-rose-200 bg-rose-50 p-3 text-rose-800"><AlertTriangle className="mt-0.5 size-4 shrink-0"/><div><p className="text-xs font-semibold">Ingresos insuficientes para cubrir compromisos</p><p className="mt-1 text-xs">Faltan <MoneyText cents={coverage.shortfallCents} currency={plan.currency}/> según el escenario base del mes.</p></div></div> : null}<div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><Metric label="Esperado" value={<MoneyText cents={period.expectedIncomeCents} currency={plan.currency} />} /><Metric label="Ingreso real" value={<MoneyText cents={actuals.incomeCents} currency={plan.currency} />} /><Metric label="Compromisos" value={<MoneyText cents={-period.plannedCommitmentsCents} currency={plan.currency} />} /><Metric label="Ahorro planificado" value={<MoneyText cents={-period.plannedSavingsCents} currency={plan.currency} />} /><Metric label="Ahorro real" value={<MoneyText cents={actuals.savingsCents} currency={plan.currency} />} /><Metric label="Disponible" value={<MoneyText cents={available} currency={plan.currency} signed />} /></div><div className="mt-4 h-1.5 overflow-hidden rounded-full bg-muted"><span className="block h-full rounded-full bg-primary" style={{ width: `${Math.min(100, period.expectedIncomeCents ? (actuals.incomeCents / period.expectedIncomeCents) * 100 : 0)}%` }} /></div></article>; })}</div> : <p className="rounded-xl border border-dashed p-8 text-center text-sm text-muted-foreground">Aún no hay meses planeados.</p>}</CardContent></Card>; }
function Metric({ label, value }: { label: string; value: any }) { return <div className="rounded-xl bg-muted/35 p-3"><p className="text-[10px] font-bold uppercase tracking-[0.1em] text-muted-foreground">{label}</p><strong className="mt-1.5 block text-sm">{value}</strong></div>; }

function planDayKey(value: Date | string) { const date = new Date(value); return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`; }
function planMonthKey(value: Date | string) { const date = new Date(value); return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}`; }
function varianceTone(value: number) { return value > 0 ? "text-rose-700" : value < 0 ? "text-emerald-700" : "text-muted-foreground"; }

function FinancialPlanCoveragePanel({ plan, periods, scenarios }: any) { return <section className="mb-5 rounded-2xl border bg-muted/15 p-4" aria-label="Cobertura de compromisos por escenario"><div className="flex flex-col gap-2 sm:flex-row sm:items-start sm:justify-between"><div><p className="eyebrow">Cobertura de obligaciones</p><h3 className="mt-1 text-base font-semibold">¿Qué parte del mes cubre cada escenario?</h3><p className="mt-1 text-xs leading-5 text-muted-foreground">La cobertura compara el ingreso proyectado del escenario con los compromisos planificados. Un déficit no ejecuta pagos ni modifica movimientos.</p></div><Badge variant="outline">{periods.length} meses · {scenarios.length} escenarios</Badge></div>{periods.length && scenarios.length ? <div className="mt-4 space-y-4">{scenarios.map((scenario: any) => <article key={scenario.id ?? scenario.title} className={`rounded-xl border p-3 ${scenarioTone[scenario.colorKey] ?? scenarioTone.slate}`}><div className="flex flex-wrap items-center justify-between gap-2"><div><p className="text-sm font-semibold">{scenario.title}</p><p className="mt-1 text-[11px] opacity-80">Ingreso mínimo: {scenario.incomeFloorCents == null ? "sin mínimo" : <MoneyText cents={scenario.incomeFloorCents} currency={plan.currency}/>}</p></div><Badge variant="outline" className="bg-white/70">{periods.filter((period: any) => financialPlanScenarioCoverage(scenario, period.plannedCommitmentsCents, period.expectedIncomeCents).isCovered).length}/{periods.length} meses cubiertos</Badge></div><div className="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{periods.map((period: any) => { const coverage = financialPlanScenarioCoverage(scenario, period.plannedCommitmentsCents, period.expectedIncomeCents); return <div key={period.id} className="rounded-lg border border-current/15 bg-white/70 p-2.5"><div className="flex items-center justify-between gap-2"><span className="text-[11px] font-semibold capitalize">{monthLabel(period.periodStart)}</span><span className="text-[11px] font-bold">{coverage.coveragePercent}%</span></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-white/80"><span className={`block h-full rounded-full ${coverage.isCovered ? "bg-emerald-500" : "bg-rose-500"}`} style={{ width: `${coverage.coveragePercent}%` }}/></div><p className="mt-1 text-[10px] opacity-80">{coverage.isCovered ? "Compromisos cubiertos" : `Déficit ${new Intl.NumberFormat("es-MX", { style: "currency", currency: plan.currency }).format(coverage.shortfallCents / 100)}`}</p></div>; })}</div></article>)}</div> : <p className="mt-4 rounded-xl border border-dashed p-4 text-sm text-muted-foreground">Añade meses y escenarios para ver la cobertura.</p>}</section>; }

function FinancialPlanComparison({ plan, periods, links, goals, transactions, scenarios, onManageLinks }: any) {
  return <Card><CardHeader className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="eyebrow">Control mensual</p><CardTitle className="mt-1">Planificado frente a real</CardTitle><CardDescription>Compara importes confirmados del proyecto con las metas manuales de cada mes. Las desviaciones no ejecutan acciones.</CardDescription></div>{onManageLinks ? <Button variant="outline" onClick={onManageLinks}><Link2 className="mr-1.5 size-4"/>Gestionar objetivos y referencias</Button> : null}</CardHeader><CardContent><FinancialPlanCoveragePanel plan={plan} periods={periods} scenarios={scenarios}/>{periods.length ? <div className="space-y-3">{periods.map((period: any) => { const actuals = actualsForFinancialPlanMonth(transactions, plan.projectId, plan.currency, period.periodStart); const periodGoals = links.filter((link: any) => link.financialPlanPeriodId === period.id && link.resourceType === "goal").map((link: any) => goals.find((goal: any) => goal.id === link.resourceId)).filter(Boolean); const rows = [{ label: "Ingresos", planned: period.expectedIncomeCents, actual: actuals.incomeCents, variance: actuals.incomeCents - period.expectedIncomeCents }, { label: "Compromisos", planned: period.plannedCommitmentsCents, actual: actuals.expenseCents, variance: actuals.expenseCents - period.plannedCommitmentsCents }, { label: "Ahorro", planned: period.plannedSavingsCents, actual: actuals.savingsCents, variance: actuals.savingsCents - period.plannedSavingsCents }]; return <article key={period.id} className="rounded-2xl border p-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><div className="flex flex-wrap items-center gap-2"><h3 className="text-sm font-semibold capitalize">{monthLabel(period.periodStart)}</h3><Badge variant="outline">{statusLabels[period.status]}</Badge></div><p className="mt-1 text-xs text-muted-foreground">{periodGoals.length ? `${periodGoals.length} objetivo${periodGoals.length === 1 ? "" : "s"} asociado${periodGoals.length === 1 ? "" : "s"}` : "Sin objetivos asociados"}</p></div><div className="flex flex-wrap gap-1">{periodGoals.slice(0, 3).map((goal: any) => <Badge key={goal.id} variant="secondary"><Target className="mr-1 size-3"/>{goal.name}</Badge>)}</div></div><div className="mt-4 grid gap-3 lg:grid-cols-3">{rows.map(row => { const scale = Math.max(row.planned, row.actual, 1); return <div key={row.label} className="rounded-xl bg-muted/30 p-3"><div className="flex items-center justify-between gap-2"><span className="text-xs font-semibold">{row.label}</span><span className={`text-xs font-semibold ${varianceTone(row.variance)}`}>{row.variance === 0 ? "En línea" : <MoneyText cents={row.variance} currency={plan.currency} signed/>}</span></div><div className="mt-3 grid grid-cols-2 gap-2 text-xs"><div><p className="text-muted-foreground">Plan</p><p className="mt-1 font-semibold"><MoneyText cents={row.planned} currency={plan.currency}/></p></div><div><p className="text-muted-foreground">Real</p><p className="mt-1 font-semibold"><MoneyText cents={row.actual} currency={plan.currency}/></p></div></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-background"><span className="block h-full rounded-full bg-primary" style={{ width: `${Math.min(100, (row.actual / scale) * 100)}%` }}/></div></div>; })}</div></article>; })}</div> : <p className="rounded-xl border border-dashed p-8 text-center text-sm text-muted-foreground">Añade meses al plan para comparar lo previsto con tus movimientos confirmados.</p>}</CardContent></Card>;
}

function FinancialPlanCalendar({ plan, periods, links, goals, tasks, calendarEvents, anchor, onAnchorChange }: any) {
  const [selectedDayKey, setSelectedDayKey] = useState<string | null>(null);
  const projectTasks = tasks.filter((task: any) => task.projectId === plan.projectId && task.dueAt && !task.archivedAt);
  const projectEvents = calendarEvents.filter((event: any) => event.projectId === plan.projectId && event.startsAt && event.status !== "cancelled");
  const monthStart = new Date(anchor.getFullYear(), anchor.getMonth(), 1);
  const offset = (monthStart.getDay() + 6) % 7;
  const daysInMonth = new Date(anchor.getFullYear(), anchor.getMonth() + 1, 0).getDate();
  const cells = Array.from({ length: offset + daysInMonth }, (_, index) => index < offset ? null : new Date(anchor.getFullYear(), anchor.getMonth(), index - offset + 1));
  const itemForDay = (date: Date) => { const key = planDayKey(date); const tasksForDay = projectTasks.filter((task: any) => planDayKey(task.dueAt) === key); const eventsForDay = projectEvents.filter((event: any) => planDayKey(event.startsAt) === key); const periodsForDay = periods.filter((period: any) => planDayKey(period.periodStart) === key); return { tasks: tasksForDay, events: eventsForDay, periods: periodsForDay }; };
  const selectedDate = selectedDayKey ? new Date(`${selectedDayKey}T12:00:00`) : null;
  const selectedItems = selectedDate ? itemForDay(selectedDate) : null;
  const weekdayLabels = ["Lun", "Mar", "Mié", "Jue", "Vie", "Sáb", "Dom"];
  const changeMonth = (amount: number) => onAnchorChange(new Date(anchor.getFullYear(), anchor.getMonth() + amount, 1));
  return <Card><CardHeader className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="eyebrow">Agenda del plan</p><CardTitle className="mt-1">Fechas, tareas y prioridades</CardTitle><CardDescription>Selecciona un día para consultar tareas y eventos del proyecto. Los meses del plan se señalan en el primer día.</CardDescription></div><div className="flex items-center gap-1"><Button size="icon" variant="outline" aria-label="Mes anterior" onClick={() => changeMonth(-1)}><ChevronLeft className="size-4"/></Button><Button variant="outline" onClick={() => onAnchorChange(new Date())}>Hoy</Button><Button size="icon" variant="outline" aria-label="Mes siguiente" onClick={() => changeMonth(1)}><ChevronRight className="size-4"/></Button></div></CardHeader><CardContent><div className="mb-3 flex items-center justify-between"><h3 className="text-base font-semibold capitalize">{monthLabel(anchor)}</h3><div className="flex flex-wrap gap-2 text-[11px] text-muted-foreground"><span className="inline-flex items-center gap-1"><span className="size-2 rounded-full bg-primary"/>Mes planificado</span><span className="inline-flex items-center gap-1"><span className="size-2 rounded-full bg-amber-500"/>Tarea</span><span className="inline-flex items-center gap-1"><span className="size-2 rounded-full bg-sky-500"/>Evento</span></div></div><div className="overflow-x-auto"><div className="min-w-[42rem]"><div className="grid grid-cols-7 gap-1">{weekdayLabels.map(label => <div key={label} className="px-2 py-1 text-center text-[10px] font-bold uppercase tracking-[0.1em] text-muted-foreground">{label}</div>)}{cells.map((date, index) => { if (!date) return <div key={`empty-${index}`} className="min-h-28 rounded-xl bg-muted/20"/>; const key = planDayKey(date); const items = itemForDay(date); const isSelected = key === selectedDayKey; const isToday = key === planDayKey(new Date()); return <button type="button" key={key} onClick={() => setSelectedDayKey(key)} className={`min-h-28 rounded-xl border p-2 text-left transition hover:border-primary/50 hover:bg-primary/5 ${isSelected ? "border-primary bg-primary/5 ring-2 ring-primary/15" : "bg-card"}`} aria-pressed={isSelected}><div className="flex items-center justify-between"><span className={`text-xs font-semibold ${isToday ? "grid size-6 place-items-center rounded-full bg-primary text-primary-foreground" : "text-muted-foreground"}`}>{date.getDate()}</span>{items.periods.length ? <CalendarDays className="size-3.5 text-primary"/> : null}</div><div className="mt-2 space-y-1">{items.periods.slice(0, 1).map((period: any) => <span key={period.id} className="block truncate rounded bg-primary/10 px-1.5 py-1 text-[10px] font-semibold text-primary">Plan: <MoneyText cents={period.expectedIncomeCents} currency={plan.currency}/></span>)}{items.tasks.slice(0, 2).map((task: any) => <span key={`task-${task.id}`} className="flex items-center gap-1 truncate rounded bg-amber-50 px-1.5 py-1 text-[10px] font-semibold text-amber-800"><ListTodo className="size-3 shrink-0"/>{task.title}</span>)}{items.events.slice(0, 2).map((event: any) => <span key={`event-${event.id}`} className="flex items-center gap-1 truncate rounded bg-sky-50 px-1.5 py-1 text-[10px] font-semibold text-sky-800"><CalendarRange className="size-3 shrink-0"/>{event.title}</span>)}{items.tasks.length + items.events.length > 4 ? <span className="block text-[10px] text-muted-foreground">+{items.tasks.length + items.events.length - 4} más</span> : null}</div></button>; })}</div></div></div>{selectedItems ? <div className="mt-4 rounded-2xl border bg-muted/20 p-4"><div className="flex flex-wrap items-center justify-between gap-2"><div><p className="eyebrow">Detalle del día</p><h3 className="mt-1 text-base font-semibold capitalize">{selectedDate?.toLocaleDateString("es-MX", { weekday: "long", day: "numeric", month: "long" })}</h3></div><Badge variant="outline">{selectedItems.tasks.length + selectedItems.events.length + selectedItems.periods.length} elementos</Badge></div>{selectedItems.periods.map((period: any) => <div key={`period-${period.id}`} className="mt-3 rounded-xl border bg-card p-3"><p className="text-sm font-semibold">Mes del plan</p><p className="mt-1 text-xs text-muted-foreground">Ingreso esperado: <MoneyText cents={period.expectedIncomeCents} currency={plan.currency}/> · Compromisos: <MoneyText cents={period.plannedCommitmentsCents} currency={plan.currency}/> · Ahorro: <MoneyText cents={period.plannedSavingsCents} currency={plan.currency}/></p>{links.filter((link: any) => link.financialPlanPeriodId === period.id && link.resourceType === "goal").map((link: any) => { const goal = goals.find((item: any) => item.id === link.resourceId); return goal ? <Badge key={link.id} className="mt-2 mr-1" variant="secondary"><Target className="mr-1 size-3"/>{goal.name}</Badge> : null; })}</div>)}{selectedItems.tasks.map((task: any) => <div key={`task-detail-${task.id}`} className="mt-2 flex items-center gap-2 rounded-xl border bg-card p-3"><Flag className="size-4 text-amber-600"/><div><p className="text-sm font-semibold">{task.title}</p><p className="text-xs text-muted-foreground">Tarea · Prioridad {task.priority ?? "media"} · {statusLabels[task.status] ?? task.status}</p></div></div>)}{selectedItems.events.map((event: any) => <div key={`event-detail-${event.id}`} className="mt-2 flex items-center gap-2 rounded-xl border bg-card p-3"><CalendarRange className="size-4 text-sky-600"/><div><p className="text-sm font-semibold">{event.title}</p><p className="text-xs text-muted-foreground">Evento · {statusLabels[event.status] ?? event.status}</p></div></div>)}</div> : <p className="mt-4 rounded-xl border border-dashed p-4 text-sm text-muted-foreground">Selecciona un día para ver sus tareas, eventos y el mes planificado.</p>}</CardContent></Card>;
}

function FinancialPlanScenarios({ plan, scenarios, levels, isOwner, onAdd, onEdit, onRemove }: any) { return <Card><CardHeader className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="eyebrow">Ingresos irregulares</p><CardTitle className="mt-1">Escenarios manuales</CardTitle><CardDescription>Define rangos y hasta qué prioridad quieres llegar. Son guías, no instrucciones de pago.</CardDescription></div>{isOwner ? <Button className="btn-primary" onClick={onAdd}><Plus className="mr-1.5 size-4"/>Escenario</Button> : null}</CardHeader><CardContent>{scenarios.length ? <div className="grid gap-3 lg:grid-cols-2">{scenarios.map((scenario: any) => <article key={scenario.id} className={`rounded-xl border p-4 ${scenarioTone[scenario.colorKey]}`}><div className="flex items-start justify-between gap-3"><div><h3 className="text-sm font-semibold">{scenario.title}</h3><p className="mt-1 text-xs">{scenario.incomeFloorCents == null ? "Sin mínimo" : <MoneyText cents={scenario.incomeFloorCents} currency={plan.currency} />} <ArrowRight className="mx-1 inline size-3"/> {scenario.incomeCeilingCents == null ? "Sin máximo" : <MoneyText cents={scenario.incomeCeilingCents} currency={plan.currency} />}</p></div>{isOwner ? <div className="flex gap-1"><Button size="icon" variant="ghost" className="size-8" aria-label={`Editar ${scenario.title}`} onClick={() => onEdit(scenario)}><Pencil className="size-3.5"/></Button><Button size="icon" variant="ghost" className="size-8" aria-label={`Eliminar ${scenario.title}`} onClick={() => onRemove(scenario)}><Trash2 className="size-3.5"/></Button></div> : null}</div><p className="mt-4 text-xs font-semibold">Cubrir hasta prioridad {scenario.allocationThroughPosition}</p>{scenario.guidance ? <p className="mt-2 text-xs leading-5">{scenario.guidance}</p> : null}</article>)}</div> : <p className="rounded-xl border border-dashed p-8 text-center text-sm text-muted-foreground">Añade escenarios como «mes malo», «base» o «bueno» según tu propia estrategia.</p>}</CardContent></Card>; }

function FinancialPlanLevels({ plan, levels, isOwner, onAdd, onEdit, onRemove }: any) { return <Card><CardHeader className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="eyebrow">Cascada de prioridades</p><CardTitle className="mt-1">Orden personal de asignación</CardTitle><CardDescription>El orden y los importes son manuales. Vincula compromisos existentes sólo si deseas mantener su referencia aquí.</CardDescription></div>{isOwner ? <Button className="btn-primary" onClick={onAdd}><Plus className="mr-1.5 size-4"/>Prioridad</Button> : null}</CardHeader><CardContent>{levels.length ? <ol className="space-y-2">{levels.map((level: any) => <li className="flex gap-3 rounded-xl border p-3.5" key={level.id}><span className="grid size-8 shrink-0 place-items-center rounded-full bg-primary text-sm font-bold text-primary-foreground">{level.position}</span><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center justify-between gap-2"><h3 className="text-sm font-semibold">{level.title}</h3><MoneyText cents={level.monthlyTargetCents} currency={plan.currency} /></div>{level.activationRule ? <p className="mt-1 text-xs leading-5 text-muted-foreground">{level.activationRule}</p> : null}{level.notes ? <p className="mt-1 text-xs leading-5 text-muted-foreground">{level.notes}</p> : null}</div>{isOwner ? <div className="flex shrink-0 gap-1"><Button size="icon" variant="ghost" aria-label={`Editar ${level.title}`} onClick={() => onEdit(level)}><Pencil className="size-4"/></Button><Button size="icon" variant="ghost" className="text-muted-foreground hover:bg-rose-50 hover:text-rose-700" aria-label={`Eliminar ${level.title}`} onClick={() => onRemove(level)}><Trash2 className="size-4"/></Button></div> : null}</li>)}</ol> : <p className="rounded-xl border border-dashed p-8 text-center text-sm text-muted-foreground">Define prioridades como liquidez mínima, obligaciones críticas, ahorro o inversión.</p>}</CardContent></Card>; }

function FinancialPlanLinks({ data, plan, levels, periods, links, isOwner, onAdd, onEdit, onRemove }: any) { const resources = useMemo(() => resourceOptions(data), [data]); const byKey = new Map(resources.map(item => [`${item.type}:${item.id}`, item])); return <Card><CardHeader className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="eyebrow">Trazabilidad</p><CardTitle className="mt-1">Referencias financieras</CardTitle><CardDescription>Los vínculos son sólo de lectura y no cambian el dato fuente.</CardDescription></div>{isOwner ? <Button className="btn-primary" onClick={onAdd}><Plus className="mr-1.5 size-4"/>Vincular referencia</Button> : null}</CardHeader><CardContent>{links.length ? <div className="divide-y rounded-xl border">{links.map((link: any) => { const resource = byKey.get(`${link.resourceType}:${link.resourceId}`); const level = levels.find((item: any) => item.id === link.financialPlanLevelId); const period = periods.find((item: any) => item.id === link.financialPlanPeriodId); return <article key={link.id} className="flex items-start gap-3 p-4"><span className="grid size-8 shrink-0 place-items-center rounded-lg bg-primary/10 text-primary"><Link2 className="size-4"/></span><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="truncate text-sm font-semibold">{resource?.label ?? "Referencia no disponible"}</p><Badge variant="outline">{resourceLabels[link.resourceType]}</Badge></div><p className="mt-1 text-xs leading-5 text-muted-foreground">{level ? `Prioridad ${level.position}: ${level.title}` : "Sin prioridad"}{period ? ` · ${monthLabel(period.periodStart)}` : ""}{link.notes ? ` · ${link.notes}` : ""}</p></div>{isOwner ? <div className="flex shrink-0 gap-1"><Button size="icon" variant="ghost" aria-label="Editar referencia" onClick={() => onEdit(link)}><Pencil className="size-4"/></Button><Button size="icon" variant="ghost" className="text-muted-foreground hover:bg-rose-50 hover:text-rose-700" aria-label="Eliminar referencia" onClick={() => onRemove(link)}><Trash2 className="size-4"/></Button></div> : null}</article>; })}</div> : <p className="rounded-xl border border-dashed p-8 text-center text-sm text-muted-foreground">Vincula de forma opcional deudas, CxP, CxC, objetivos, tareas, presupuestos, eventos, revisiones o documentos.</p>}</CardContent></Card>; }

function FinancialPlanForm({ plan, projects, defaultProjectId, saving, onSubmit }: any) { const [form, setForm] = useState(() => plan ? { ...plan, projectId: String(plan.projectId), startsAt: dateInputValue(plan.startsAt), endsAt: dateInputValue(plan.endsAt), guidingRule: plan.guidingRule ?? "", notes: plan.notes ?? "" } : { projectId: String(defaultProjectId), title: "", currency: "MXN", status: "draft", startsAt: "", endsAt: "", guidingRule: "Asignar ingresos confirmados por prioridad, no por expectativa.", notes: "" }); const submit = (event: FormEvent) => { event.preventDefault(); onSubmit({ id: plan?.id, projectId: Number(form.projectId), title: form.title, currency: form.currency.toUpperCase(), status: form.status, startsAt: asDateTimestamp(form.startsAt), endsAt: asDateTimestamp(form.endsAt), guidingRule: form.guidingRule || null, notes: form.notes || null }); }; return <DialogContent className="max-h-[92dvh] overflow-y-auto sm:max-w-xl"><DialogHeader><p className="eyebrow">Plan financiero</p><DialogTitle>{plan ? "Editar plan financiero" : "Crear plan financiero"}</DialogTitle><DialogDescription>La planificación no crea movimientos, presupuestos ni pagos. Todo dato financiero enlazado conserva su módulo de origen.</DialogDescription></DialogHeader><form className="grid gap-4 py-2" onSubmit={submit}><div className="grid gap-2"><Label>Proyecto</Label><Select value={form.projectId} onValueChange={projectId => setForm({ ...form, projectId })}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{projects.map((project: any) => <SelectItem key={project.id} value={String(project.id)}>{project.name}</SelectItem>)}</SelectContent></Select></div><div className="grid gap-4 sm:grid-cols-[1fr_8rem]"><div className="grid gap-2"><Label>Título</Label><Input required value={form.title} onChange={event => setForm({ ...form, title: event.target.value })} placeholder="Plan financiero Jul–Dic 2026"/></div><div className="grid gap-2"><Label>Moneda</Label><Input required maxLength={3} value={form.currency} onChange={event => setForm({ ...form, currency: event.target.value.toUpperCase() })}/></div></div><div className="grid gap-4 sm:grid-cols-3"><div className="grid gap-2"><Label>Estado</Label><Select value={form.status} onValueChange={status => setForm({ ...form, status })}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{["draft", "active", "completed", "archived"].map(status => <SelectItem key={status} value={status}>{statusLabels[status]}</SelectItem>)}</SelectContent></Select></div><div className="grid gap-2"><Label>Inicio</Label><Input type="date" value={form.startsAt} onChange={event => setForm({ ...form, startsAt: event.target.value })}/></div><div className="grid gap-2"><Label>Fin</Label><Input type="date" value={form.endsAt} onChange={event => setForm({ ...form, endsAt: event.target.value })}/></div></div><div className="grid gap-2"><Label>Regla guía</Label><Textarea value={form.guidingRule} onChange={event => setForm({ ...form, guidingRule: event.target.value })} maxLength={3000} placeholder="Por ejemplo: asignar ingresos confirmados por prioridad, no por expectativa."/></div><div className="grid gap-2"><Label>Notas privadas</Label><Textarea value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} maxLength={5000}/></div><Button type="submit" className="btn-primary" disabled={saving}>{saving ? "Guardando…" : "Guardar plan"}</Button></form></DialogContent>; }

function LevelForm({ item, plan, saving, onSubmit }: any) { const [form, setForm] = useState(() => item ? { ...item, monthlyTarget: inputFromCents(item.monthlyTargetCents), activationRule: item.activationRule ?? "", notes: item.notes ?? "" } : { position: "0", title: "", monthlyTarget: "", activationRule: "", notes: "" }); const submit = (event: FormEvent) => { event.preventDefault(); onSubmit({ id: item?.id, financialPlanId: plan.id, position: Number(form.position), title: form.title, monthlyTargetCents: centsFromInput(form.monthlyTarget), activationRule: form.activationRule || null, notes: form.notes || null }); }; return <DialogContent className="sm:max-w-lg"><DialogHeader><p className="eyebrow">Cascada de prioridades</p><DialogTitle>{item ? "Editar prioridad" : "Nueva prioridad"}</DialogTitle><DialogDescription>Es una guía manual de asignación, no una orden de pago.</DialogDescription></DialogHeader><form className="grid gap-4 py-2" onSubmit={submit}><div className="grid gap-4 sm:grid-cols-[7rem_1fr]"><div className="grid gap-2"><Label>Orden</Label><Input type="number" min="0" max="99" required value={form.position} onChange={event => setForm({ ...form, position: event.target.value })}/></div><div className="grid gap-2"><Label>Prioridad</Label><Input required value={form.title} onChange={event => setForm({ ...form, title: event.target.value })} placeholder="Liquidez mínima"/></div></div><div className="grid gap-2"><Label>Importe mensual orientativo ({plan.currency})</Label><Input inputMode="decimal" value={form.monthlyTarget} onChange={event => setForm({ ...form, monthlyTarget: event.target.value })} placeholder="0.00"/></div><div className="grid gap-2"><Label>Condición de activación</Label><Textarea value={form.activationRule} onChange={event => setForm({ ...form, activationRule: event.target.value })} maxLength={2000} placeholder="Ej. Sólo después de cubrir obligaciones críticas."/></div><div className="grid gap-2"><Label>Notas</Label><Textarea value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} maxLength={3000}/></div><Button type="submit" className="btn-primary" disabled={saving}>{saving ? "Guardando…" : "Guardar prioridad"}</Button></form></DialogContent>; }

function ScenarioForm({ item, plan, levels, saving, onSubmit }: any) { const [form, setForm] = useState(() => item ? { ...item, incomeFloor: inputFromCents(item.incomeFloorCents), incomeCeiling: inputFromCents(item.incomeCeilingCents), guidance: item.guidance ?? "" } : { title: "", incomeFloor: "", incomeCeiling: "", allocationThroughPosition: "0", guidance: "", colorKey: "slate" }); const submit = (event: FormEvent) => { event.preventDefault(); onSubmit({ id: item?.id, financialPlanId: plan.id, title: form.title, incomeFloorCents: form.incomeFloor === "" ? null : centsFromInput(form.incomeFloor), incomeCeilingCents: form.incomeCeiling === "" ? null : centsFromInput(form.incomeCeiling), allocationThroughPosition: Number(form.allocationThroughPosition), guidance: form.guidance || null, colorKey: form.colorKey }); }; return <DialogContent className="sm:max-w-lg"><DialogHeader><p className="eyebrow">Escenarios de ingresos</p><DialogTitle>{item ? "Editar escenario" : "Nuevo escenario"}</DialogTitle><DialogDescription>Define un rango manual y hasta qué prioridad deseas cubrir cuando el ingreso confirmado coincida.</DialogDescription></DialogHeader><form className="grid gap-4 py-2" onSubmit={submit}><div className="grid gap-2"><Label>Nombre</Label><Input required value={form.title} onChange={event => setForm({ ...form, title: event.target.value })} placeholder="Mes base"/></div><div className="grid gap-4 sm:grid-cols-2"><div className="grid gap-2"><Label>Ingreso mínimo ({plan.currency})</Label><Input inputMode="decimal" value={form.incomeFloor} onChange={event => setForm({ ...form, incomeFloor: event.target.value })} placeholder="Sin mínimo"/></div><div className="grid gap-2"><Label>Ingreso máximo ({plan.currency})</Label><Input inputMode="decimal" value={form.incomeCeiling} onChange={event => setForm({ ...form, incomeCeiling: event.target.value })} placeholder="Sin máximo"/></div></div><div className="grid gap-4 sm:grid-cols-2"><div className="grid gap-2"><Label>Hasta prioridad</Label><Select value={String(form.allocationThroughPosition)} onValueChange={allocationThroughPosition => setForm({ ...form, allocationThroughPosition })}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="0">Sólo obligaciones base</SelectItem>{levels.map((level: any) => <SelectItem key={level.id} value={String(level.position)}>Prioridad {level.position}: {level.title}</SelectItem>)}</SelectContent></Select></div><div className="grid gap-2"><Label>Color</Label><Select value={form.colorKey} onValueChange={colorKey => setForm({ ...form, colorKey })}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{Object.entries({ rose: "Rosa", amber: "Ámbar", sky: "Azul", emerald: "Verde", slate: "Neutro" }).map(([value, label]) => <SelectItem key={value} value={value}>{label}</SelectItem>)}</SelectContent></Select></div></div><div className="grid gap-2"><Label>Guía</Label><Textarea value={form.guidance} onChange={event => setForm({ ...form, guidance: event.target.value })} maxLength={3000} placeholder="Ej. Detener asignaciones no críticas si el ingreso es inferior al mínimo."/></div><Button type="submit" className="btn-primary" disabled={saving}>{saving ? "Guardando…" : "Guardar escenario"}</Button></form></DialogContent>; }

function PeriodForm({ item, plan, saving, onSubmit }: any) { const [form, setForm] = useState(() => item ? { ...item, periodStart: monthInputValue(item.periodStart), expectedIncome: inputFromCents(item.expectedIncomeCents), plannedCommitments: inputFromCents(item.plannedCommitmentsCents), plannedSavings: inputFromCents(item.plannedSavingsCents), notes: item.notes ?? "" } : { periodStart: "", expectedIncome: "", plannedCommitments: "", plannedSavings: "", status: "draft", notes: "" }); const submit = (event: FormEvent) => { event.preventDefault(); const monthTimestamp = form.periodStart ? new Date(`${form.periodStart}-01T12:00:00`).getTime() : 0; onSubmit({ id: item?.id, financialPlanId: plan.id, periodStart: monthTimestamp, expectedIncomeCents: centsFromInput(form.expectedIncome), plannedCommitmentsCents: centsFromInput(form.plannedCommitments), plannedSavingsCents: centsFromInput(form.plannedSavings), status: form.status, notes: form.notes || null }); }; return <DialogContent className="sm:max-w-lg"><DialogHeader><p className="eyebrow">Vista mensual</p><DialogTitle>{item ? "Editar mes del plan" : "Añadir mes al plan"}</DialogTitle><DialogDescription>Los valores son expectativas manuales. La vista compara contra movimientos confirmados sin crear un cierre.</DialogDescription></DialogHeader><form className="grid gap-4 py-2" onSubmit={submit}><div className="grid gap-4 sm:grid-cols-2"><div className="grid gap-2"><Label>Mes</Label><Input type="month" required value={form.periodStart} onChange={event => setForm({ ...form, periodStart: event.target.value })}/></div><div className="grid gap-2"><Label>Estado</Label><Select value={form.status} onValueChange={status => setForm({ ...form, status })}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{["draft", "in_review", "complete"].map(status => <SelectItem key={status} value={status}>{statusLabels[status]}</SelectItem>)}</SelectContent></Select></div></div><div className="grid gap-4 sm:grid-cols-3"><div className="grid gap-2"><Label>Ingreso esperado</Label><Input inputMode="decimal" value={form.expectedIncome} onChange={event => setForm({ ...form, expectedIncome: event.target.value })} placeholder="0.00"/></div><div className="grid gap-2"><Label>Compromisos</Label><Input inputMode="decimal" value={form.plannedCommitments} onChange={event => setForm({ ...form, plannedCommitments: event.target.value })} placeholder="0.00"/></div><div className="grid gap-2"><Label>Ahorro</Label><Input inputMode="decimal" value={form.plannedSavings} onChange={event => setForm({ ...form, plannedSavings: event.target.value })} placeholder="0.00"/></div></div><div className="grid gap-2"><Label>Notas del mes</Label><Textarea value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} maxLength={3000}/></div><Button type="submit" className="btn-primary" disabled={saving}>{saving ? "Guardando…" : "Guardar mes"}</Button></form></DialogContent>; }

function LinkForm({ item, data, plan, levels, periods, saving, onSubmit }: any) { const resources = useMemo(() => resourceOptions(data), [data]); const [form, setForm] = useState(() => item ? { ...item, financialPlanLevelId: item.financialPlanLevelId ? String(item.financialPlanLevelId) : "none", financialPlanPeriodId: item.financialPlanPeriodId ? String(item.financialPlanPeriodId) : "none", resourceType: item.resourceType, resourceId: String(item.resourceId), notes: item.notes ?? "" } : { financialPlanLevelId: "none", financialPlanPeriodId: "none", resourceType: resources[0]?.type ?? "debt", resourceId: String(resources[0]?.id ?? ""), notes: "" }); const resourcesOfType = resources.filter(resource => resource.type === form.resourceType); const submit = (event: FormEvent) => { event.preventDefault(); onSubmit({ id: item?.id, financialPlanId: plan.id, financialPlanLevelId: form.financialPlanLevelId === "none" ? null : Number(form.financialPlanLevelId), financialPlanPeriodId: form.financialPlanPeriodId === "none" ? null : Number(form.financialPlanPeriodId), resourceType: form.resourceType, resourceId: Number(form.resourceId), notes: form.notes || null }); }; const changeType = (resourceType: string) => { const next = resources.find(resource => resource.type === resourceType); setForm({ ...form, resourceType, resourceId: String(next?.id ?? "") }); }; return <DialogContent className="max-h-[92dvh] overflow-y-auto sm:max-w-lg"><DialogHeader><p className="eyebrow">Referencia financiera</p><DialogTitle>{item ? "Editar referencia" : "Vincular referencia"}</DialogTitle><DialogDescription>El vínculo es informativo; nunca modifica el saldo, estado ni fecha de la referencia original.</DialogDescription></DialogHeader><form className="grid gap-4 py-2" onSubmit={submit}><div className="grid gap-4 sm:grid-cols-2"><div className="grid gap-2"><Label>Tipo</Label><Select value={form.resourceType} onValueChange={changeType}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{Object.entries(resourceLabels).map(([value, label]) => <SelectItem key={value} value={value}>{label}</SelectItem>)}</SelectContent></Select></div><div className="grid gap-2"><Label>Referencia</Label><Select value={form.resourceId} onValueChange={resourceId => setForm({ ...form, resourceId })}><SelectTrigger><SelectValue placeholder="Selecciona"/></SelectTrigger><SelectContent>{resourcesOfType.length ? resourcesOfType.map(resource => <SelectItem key={`${resource.type}:${resource.id}`} value={String(resource.id)}>{resource.label}</SelectItem>) : <SelectItem value="none" disabled>Sin referencias disponibles</SelectItem>}</SelectContent></Select></div></div><div className="grid gap-4 sm:grid-cols-2"><div className="grid gap-2"><Label>Prioridad <span className="font-normal text-muted-foreground">(opcional)</span></Label><Select value={form.financialPlanLevelId} onValueChange={financialPlanLevelId => setForm({ ...form, financialPlanLevelId })}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="none">Sin prioridad</SelectItem>{levels.map((level: any) => <SelectItem key={level.id} value={String(level.id)}>{level.position}. {level.title}</SelectItem>)}</SelectContent></Select></div><div className="grid gap-2"><Label>Mes <span className="font-normal text-muted-foreground">(opcional)</span></Label><Select value={form.financialPlanPeriodId} onValueChange={financialPlanPeriodId => setForm({ ...form, financialPlanPeriodId })}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="none">Sin mes</SelectItem>{periods.map((period: any) => <SelectItem key={period.id} value={String(period.id)}>{monthLabel(period.periodStart)}</SelectItem>)}</SelectContent></Select></div></div><div className="grid gap-2"><Label>Nota de contexto</Label><Textarea value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} maxLength={2000}/></div><Button type="submit" className="btn-primary" disabled={saving || !form.resourceId || form.resourceId === "none"}>{saving ? "Guardando…" : "Guardar referencia"}</Button></form></DialogContent>; }

function resourceOptions(data: WorkspaceData) { const options: Array<{ type: string; id: number; label: string }> = []; const add = (type: string, rows: any[], label: (row: any) => string) => rows.forEach(row => options.push({ type, id: row.id, label: label(row) })); add("budget", data.budgets ?? [], row => `${row.type === "income" ? "Presupuesto de ingreso" : "Presupuesto"} #${row.id}`); add("debt", data.debts ?? [], row => row.name); add("credit_card", data.creditCards ?? [], row => row.name); add("payable", data.payables ?? [], row => row.description || row.name || `Cuenta por pagar #${row.id}`); add("receivable", data.receivables ?? [], row => row.description || row.name || `Cuenta por cobrar #${row.id}`); add("goal", data.goals ?? [], row => row.name); add("task", data.tasks ?? [], row => row.title); add("calendar_event", data.calendarEvents ?? [], row => row.title); add("fiscal_review", data.fiscalPeriodReviews ?? [], row => `Revisión fiscal ${monthLabel(row.periodStart)}`); add("document", data.documents ?? [], row => row.name); return options; }
